import { useCallback, useEffect, useState } from "react";

/**
 * Persisted state backed by localStorage, synced across tabs via the
 * `storage` event.
 *
 * - Reads lazily: localStorage is only touched on first render.
 * - Writes JSON on every set (value or functional updater).
 * - Falls back to `initial` when stored JSON is malformed instead of throwing.
 * - Another tab's write to the same key updates this hook's state
 *   (via the window `storage` event).
 */
export function useLocalStorage(key, initial) {
  const [state, setState] = useState(() => {
    try {
      const raw = window.localStorage.getItem(key);
      if (raw === null) return initial;
      return JSON.parse(raw);
    } catch {
      return initial;
    }
  });

  const set = useCallback(
    (value) => {
      setState((prev) => {
        const next =
          typeof value === "function" ? value(prev) : value;
        try {
          window.localStorage.setItem(key, JSON.stringify(next));
        } catch {
          // Storage full or unavailable; keep in-memory state.
        }
        return next;
      });
    },
    [key]
  );

  useEffect(() => {
    const onStorage = (event) => {
      if (event.key !== key) return;
      try {
        const raw = event.newValue;
        if (raw === null) {
          // Key was removed in the other tab.
          setState(initial);
          return;
        }
        setState(JSON.parse(raw));
      } catch {
        setState(initial);
      }
    };
    window.addEventListener("storage", onStorage);
    return () => window.removeEventListener("storage", onStorage);
  }, [key, initial]);

  return [state, set];
}

