import { describe, expect, it, beforeEach, vi } from "vitest";
import { renderHook, act } from "@testing-library/react";
import { useLocalStorage } from "./use-local-storage.js";

beforeEach(() => {
  window.localStorage.clear();
});

describe("useLocalStorage", () => {
  it("reads lazily and returns initial when nothing is stored", () => {
    const getItemSpy = vi.spyOn(Storage.prototype, "getItem");
    const { result } = renderHook(() =>
      useLocalStorage("count", 42)
    );
    expect(result.current[0]).toBe(42);
    // No read happened before render's initializer ran... but exactly one
    // lazy read happens during first render, not on re-renders.
    expect(getItemSpy).toHaveBeenCalledTimes(1);
    act(() => result.current[1](43));
    expect(getItemSpy).toHaveBeenCalledTimes(1); // no extra reads
    getItemSpy.mockRestore();
  });

  it("set persists JSON to localStorage", () => {
    const { result } = renderHook(() =>
      useLocalStorage("user", { name: "a" })
    );
    act(() => result.current[1]({ name: "b" }));
    expect(window.localStorage.getItem("user")).toBe('{"name":"b"}');
    expect(result.current[0]).toEqual({ name: "b" });
  });

  it("supports functional updates based on previous state", () => {
    const { result } = renderHook(() => useLocalStorage("n", 10));
    act(() => result.current[1]((prev) => prev + 5));
    act(() => result.current[1]((prev) => prev * 2));
    expect(result.current[0]).toBe(30);
    expect(window.localStorage.getItem("n")).toBe("30");
  });

  it("falls back to initial on corrupted stored JSON without throwing", () => {
    window.localStorage.setItem("bad", "{not json!!");
    const { result } = renderHook(() =>
      useLocalStorage("bad", { safe: true })
    );
    expect(result.current[0]).toEqual({ safe: true });
  });

  it("ignores storage events for foreign keys", () => {
    const { result } = renderHook(() => useLocalStorage("mine", 1));
    act(() =>
      window.dispatchEvent(
        new StorageEvent("storage", { key: "theirs", newValue: "99" })
      )
    );
    expect(result.current[0]).toBe(1);
  });

  it("updates state on a matching-key storage event from another tab", () => {
    const { result } = renderHook(() => useLocalStorage("shared", 1));
    act(() =>
      window.dispatchEvent(
        new StorageEvent("storage", { key: "shared", newValue: '{"v":7}' })
      )
    );
    expect(result.current[0]).toEqual({ v: 7 });

    // Corrupted payload from the other tab falls back to initial.
    act(() =>
      window.dispatchEvent(
        new StorageEvent("storage", { key: "shared", newValue: "oops{" })
      )
    );
    expect(result.current[0]).toBe(1);
  });
});

